from typing import List
import bisect
class Solution:
    def canMakePalindromeQueries(self, s: str, queries: List[List[int]]) -> List[bool]:
        n = len(s); m = n // 2
        pref = [[0] * 26]
        for ch in s:
            row = pref[-1][:]
            row[ord(ch) - 97] += 1
            pref.append(row)
        def cnt(l, r, c):
            return pref[r + 1][c] - pref[l][c] if l <= r else 0
        mm = [i for i in range(m) if s[i] != s[n - 1 - i]]
        def mism(lo, hi):
            if lo > hi: return 0
            return bisect.bisect_right(mm, hi) - bisect.bisect_left(mm, lo)
        res = []
        for a, b, c, d in queries:
            la, lb = n - 1 - d, n - 1 - c
            lo, hi = min(a, la), max(b, lb)
            ok = mism(0, lo - 1) == 0 and mism(hi + 1, m - 1) == 0
            if ok:
                ia, ib = max(a, la), min(b, lb)
                ja, jb = max(c, n - 1 - b), min(d, n - 1 - a)
                for ch in range(26):
                    lc = cnt(a, b, ch) + cnt(la, lb, ch) - cnt(ia, ib, ch)
                    rc = cnt(c, d, ch) + cnt(n - 1 - b, n - 1 - a, ch) - cnt(ja, jb, ch)
                    if lc != rc:
                        ok = False
                        break
            res.append(ok)
        return res

