class Solution {
public:
    vector<bool> canMakePalindromeQueries(string s, vector<vector<int>>& queries) {
        int n = s.size(), m = n / 2;
        vector<array<int,26>> pref(n + 1);
        pref[0].fill(0);
        for (int i = 0; i < n; i++) {
            pref[i + 1] = pref[i];
            pref[i + 1][s[i] - 'a']++;
        }
        auto cnt = [&](int l, int r, int c) {
            return l <= r ? pref[r + 1][c] - pref[l][c] : 0;
        };
        vector<int> mm;
        for (int i = 0; i < m; i++)
            if (s[i] != s[n - 1 - i]) mm.push_back(i);
        auto mism = [&](int lo, int hi) {
            if (lo > hi) return 0;
            return (int)(upper_bound(mm.begin(), mm.end(), hi) - lower_bound(mm.begin(), mm.end(), lo));
        };
        vector<bool> res;
        for (auto& q : queries) {
            int a = q[0], b = q[1], c = q[2], d = q[3];
            int la = n - 1 - d, lb = n - 1 - c;
            int lo = min(a, la), hi = max(b, lb);
            bool ok = mism(0, lo - 1) == 0 && mism(hi + 1, m - 1) == 0;
            if (ok) {
                int ia = max(a, la), ib = min(b, lb);
                int ja = max(c, n - 1 - b), jb = min(d, n - 1 - a);
                for (int ch = 0; ch < 26 && ok; ch++) {
                    int lc = cnt(a, b, ch) + cnt(la, lb, ch) - cnt(ia, ib, ch);
                    int rc = cnt(c, d, ch) + cnt(n - 1 - b, n - 1 - a, ch) - cnt(ja, jb, ch);
                    if (lc != rc) ok = false;
                }
            }
            res.push_back(ok);
        }
        return res;
    }
};

