class Solution {
    public List<Boolean> canMakePalindromeQueries(String s, int[][] queries) {
        int n = s.length(), m = n / 2;
        int[][] pref = new int[n + 1][26];
        for (int i = 0; i < n; i++) {
            pref[i + 1] = pref[i].clone();
            pref[i + 1][s.charAt(i) - 'a']++;
        }
        List<Integer> mm = new ArrayList<>();
        for (int i = 0; i < m; i++)
            if (s.charAt(i) != s.charAt(n - 1 - i)) mm.add(i);
        List<Boolean> res = new ArrayList<>();
        for (int[] q : queries) {
            int a = q[0], b = q[1], c = q[2], d = q[3];
            int la = n - 1 - d, lb = n - 1 - c;
            int lo = Math.min(a, la), hi = Math.max(b, lb);
            boolean ok = mism(mm, 0, lo - 1) == 0 && mism(mm, hi + 1, m - 1) == 0;
            if (ok) {
                int ia = Math.max(a, la), ib = Math.min(b, lb);
                int ja = Math.max(c, n - 1 - b), jb = Math.min(d, n - 1 - a);
                for (int ch = 0; ch < 26 && ok; ch++) {
                    int lc = cnt(pref, a, b, ch) + cnt(pref, la, lb, ch) - cnt(pref, ia, ib, ch);
                    int rc = cnt(pref, c, d, ch) + cnt(pref, n - 1 - b, n - 1 - a, ch) - cnt(pref, ja, jb, ch);
                    if (lc != rc) ok = false;
                }
            }
            res.add(ok);
        }
        return res;
    }
    private int cnt(int[][] pref, int l, int r, int c) {
        return l <= r ? pref[r + 1][c] - pref[l][c] : 0;
    }
    private int mism(List<Integer> mm, int lo, int hi) {
        if (lo > hi) return 0;
        return ub(mm, hi) - lb(mm, lo);
    }
    private int lb(List<Integer> a, int x) {
        int lo = 0, hi = a.size();
        while (lo < hi) { int md = (lo + hi) >>> 1; if (a.get(md) < x) lo = md + 1; else hi = md; }
        return lo;
    }
    private int ub(List<Integer> a, int x) {
        int lo = 0, hi = a.size();
        while (lo < hi) { int md = (lo + hi) >>> 1; if (a.get(md) <= x) lo = md + 1; else hi = md; }
        return lo;
    }
};

