var canMakePalindromeQueries = function(s, queries) {
    const n = s.length, m = n >> 1;
    const pref = [new Array(26).fill(0)];
    for (const ch of s) {
        const row = pref[pref.length - 1].slice();
        row[ch.charCodeAt(0) - 97]++;
        pref.push(row);
    }
    const cnt = (l, r, c) => (l <= r ? pref[r + 1][c] - pref[l][c] : 0);
    const mm = [];
    for (let i = 0; i < m; i++)
        if (s[i] !== s[n - 1 - i]) mm.push(i);
    const lb = (a, x) => { let lo = 0, hi = a.length; while (lo < hi) { const md = (lo + hi) >> 1; if (a[md] < x) lo = md + 1; else hi = md; } return lo; };
    const ub = (a, x) => { let lo = 0, hi = a.length; while (lo < hi) { const md = (lo + hi) >> 1; if (a[md] <= x) lo = md + 1; else hi = md; } return lo; };
    const mism = (lo, hi) => (lo > hi ? 0 : ub(mm, hi) - lb(mm, lo));
    return queries.map(([a, b, c, d]) => {
        const la = n - 1 - d, lb2 = n - 1 - c;
        const lo = Math.min(a, la), hi = Math.max(b, lb2);
        let ok = mism(0, lo - 1) === 0 && mism(hi + 1, m - 1) === 0;
        if (ok) {
            const ia = Math.max(a, la), ib = Math.min(b, lb2);
            const ja = Math.max(c, n - 1 - b), jb = Math.min(d, n - 1 - a);
            for (let ch = 0; ch < 26 && ok; ch++) {
                const lc = cnt(a, b, ch) + cnt(la, lb2, ch) - cnt(ia, ib, ch);
                const rc = cnt(c, d, ch) + cnt(n - 1 - b, n - 1 - a, ch) - cnt(ja, jb, ch);
                if (lc !== rc) ok = false;
            }
        }
        return ok;
    });
};
